                    <div class="data-bar-track"><div class="data-bar-fill" style="width: 17%;"></div></div>
                </div>
                <div class="data-bar-container">
                    <div class="data-bar-label"><span>Google Cloud</span> <span>11%</span></div>
                    <div class="data-bar-track"><div class="data-bar-fill" style="width: 11%;"></div></div>
                </div>
            </div>
        </div>

        <!-- PLATFORMS -->
