                    <div class="platform-val">58%</div>
                    <div class="platform-name">Browser</div>
                </div>
                <div class="platform-card">
                    <div class="platform-val">56%</div>
                    <div class="platform-name">Server / Cloud</div>
                </div>
                <div class="platform-card">
                    <div class="platform-val">53%</div>
                    <div class="platform-name">Desktop</div>
