    <script>
        // Data for JS, Python, TS
        const dataJS = [65, 69, 69, 61, 61];
        const dataPy = [32, 49, 52, 54, 57];
        const dataTS = [12, 25, 29, 34, 37];

        // Render Chart
        window.onload = () => {
            const svg = document.getElementById('svg-chart');
            const w = svg.clientWidth;
            const h = svg.clientHeight;

            const paddingLeft = 140;
            const paddingRight = 140;
            const paddingTop = 60;
            const paddingBottom = 60;

            const chartW = w - paddingLeft - paddingRight;
            const chartH = h - paddingTop - paddingBottom;

            const maxVal = 70;

            function getCoords(dataIndex, value) {
                const x = paddingLeft + (dataIndex / 4) * chartW;
                const y = paddingTop + chartH - (value / maxVal) * chartH;
                return {x, y};
            }

            function drawLine(data, className) {
                let d = "";
                data.forEach((val, i) => {
                    const {x, y} = getCoords(i, val);
                    if(i === 0) d += `M \${x} \${y} `;
                    else d += `L \${x} \${y} `;
                });

                const path = document.createElementNS('http://www.w3.org/2000/svg', 'path');
                path.setAttribute('d', d);
                path.setAttribute('class', className);
                svg.appendChild(path);

                // Draw points and labels
                data.forEach((val, i) => {
                    const {x, y} = getCoords(i, val);

                    const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
                    circle.setAttribute('cx', x);
                    circle.setAttribute('cy', y);
                    circle.setAttribute('r', '12');
                    circle.setAttribute('class', `data-point dp-\${className.split('-')[1]}`);
                    svg.appendChild(circle);

                    const text = document.createElementNS('http://www.w3.org/2000/svg', 'text');
                    text.setAttribute('x', x);
                    text.setAttribute('y', y - 25);
                    text.setAttribute('text-anchor', 'middle');
                    text.setAttribute('class', 'data-label');
                    text.textContent = val + '%';
                    svg.appendChild(text);
                });
            }

            drawLine(dataJS, 'line-js');
            drawLine(dataPy, 'line-py');
            drawLine(dataTS, 'line-ts');
        };
    </script>
</body>
</html>
`;

